import 'server-only';
import { logError } from './audit';
import { db } from './db';
import { mediaKeyFromPath, storage, storeTenantImage, variantKeys } from './storage';

/**
 * Lifecycle of tenant images (logos, covers, dish photos) around database changes.
 *
 * Tenant rule: an organization only ever writes or deletes objects under its own
 * `<organizationId>/` prefix. Keys are generated by the server from the authenticated
 * tenant context, never taken from the request.
 */

/**
 * Stores the given uploads for `organizationId`, then runs `fn` with their media paths.
 * If `fn` throws (validation, authorization, database error) the new files are deleted again,
 * so failed requests leave no orphaned objects.
 */
export async function withStoredImages<K extends string, T>(
  organizationId: string,
  uploads: Partial<Record<K, { file: File; folder: 'branding' | 'products' }>>,
  fn: (paths: Partial<Record<K, string>>) => Promise<T>,
): Promise<T> {
  const paths: Partial<Record<K, string>> = {};
  try {
    for (const [name, u] of Object.entries(uploads) as [K, { file: File; folder: 'branding' | 'products' } | undefined][]) {
      if (u) paths[name] = await storeTenantImage(organizationId, u.file, u.folder);
    }
    return await fn(paths);
  } catch (e) {
    await deleteTenantMedia(organizationId, Object.values(paths) as string[], { force: true });
    throw e;
  }
}

/**
 * Deletes stored objects for media paths that belong to `organizationId` and are no longer
 * referenced anywhere in the database. Paths of other tenants, external URLs and malformed
 * values are ignored. Best effort: a storage failure is logged, never shown to the user
 * (the database change already succeeded; an orphaned object is harmless).
 *
 * `force` skips the reference check; only for files created in the same failed request.
 */
export async function deleteTenantMedia(organizationId: string, mediaPaths: (string | null | undefined)[], opts: { force?: boolean } = {}) {
  const deleted: string[] = [];
  for (const p of new Set(mediaPaths)) {
    const key = mediaKeyFromPath(p);
    if (!key || !key.startsWith(`${organizationId}/`)) continue;
    try {
      if (!opts.force && (await isReferenced(p!))) continue;
      // The resized copies go with it, so a removed photo is not served at any size.
      await storage.deleteMany([key, ...variantKeys(key)]);
      deleted.push(key);
    } catch (e) {
      await logError('media-delete', e, { organizationId, key });
    }
  }
  return deleted;
}

async function isReferenced(mediaPath: string) {
  const [branding, images, reviewPhotos] = await Promise.all([
    db.restaurantBranding.count({ where: { OR: [{ logoUrl: mediaPath }, { coverUrl: mediaPath }] } }),
    db.productImage.count({ where: { url: mediaPath } }),
    // A photo uploaded while reviewing an import that is still open.
    db.importedProduct.count({ where: { imageUrl: mediaPath, job: { status: { in: ['DRAFT', 'NEEDS_REVIEW'] } } } }),
  ]);
  return branding + images + reviewPhotos > 0;
}
